#!/usr/bin/env sage
"""
Error ratio analysis with CORRECT P2.7 recurrence.

The recurrence is:
  u_{n+1} = (B_n/A_n) u_n - (C_{n-1}/A_{n-1}) u_{n-1} + (D_{n-2}/A_{n-2}) u_{n-2}

Key question: what is the relationship between e_n^{P27} and e_n^{Zudilin}?

Both errors are purely subdominant (c₀ = 0 for each).
Zudilin: |e^Z| ~ |μ₁|^n ≈ 0.067^n, σ₁ = -3/2
P2.7:    |e^P| ~ |μ₁/64|^n ≈ 0.00105^n, σ₁ ≈ -12

The 64-scaled ratio: e^P / (64^{-n} · e^Z) ~ n^{σ₁^P - σ₁^Z} = n^{-10.5}
"""


# This file was *autogenerated* from the file scratchpad/error_ratio_fixed.sage
from sage.all_cmdline import *   # import sage library

_sage_const_500 = Integer(500); _sage_const_50 = Integer(50); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_40 = Integer(40); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_20 = Integer(20); _sage_const_7425 = Integer(7425); _sage_const_16 = Integer(16); _sage_const_1024 = Integer(1024); _sage_const_5 = Integer(5); _sage_const_7 = Integer(7); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_215040420000 = Integer(215040420000); _sage_const_167282265043404 = Integer(167282265043404); _sage_const_905 = Integer(905); _sage_const_964185327658080 = Integer(964185327658080); _sage_const_6071 = Integer(6071); _sage_const_612218384750 = Integer(612218384750); _sage_const_9525021973931919 = Integer(9525021973931919); _sage_const_18100 = Integer(18100); _sage_const_29561828382772029 = Integer(29561828382772029); _sage_const_65380 = Integer(65380); _sage_const_25 = Integer(25); _sage_const_12 = Integer(12); _sage_const_15 = Integer(15); _sage_const_64 = Integer(64); _sage_const_30 = Integer(30)
from ore_algebra import OreAlgebra, guess
import mpmath
mpmath.mp.dps = _sage_const_500 

N = _sage_const_50 

# ============================================================
# Compute a_n and rec_a
# ============================================================
a_list = []
for i in range(N):
    val = QQ(_sage_const_0 )
    for k in range(i+_sage_const_1 ):
        val += binomial(i,k)**_sage_const_2  * binomial(i+k,i) * binomial(i+_sage_const_2 *k,i)
    a_list.append(val)

Rn = PolynomialRing(QQ, 'nn')
nn_var = Rn.gen()
OS = OreAlgebra(Rn, 'Snn')
Snn = OS.gen()

rec_a_op = guess(a_list[:_sage_const_40 ], OS, order=_sage_const_3 )
P_rec = [rec_a_op[j] for j in range(_sage_const_4 )]

# ============================================================
# Zudilin companion p̃_n via rec_a
# ============================================================
p_zud = [QQ(_sage_const_0 )] * N
p_zud[_sage_const_0 ] = QQ(_sage_const_0 )
p_zud[_sage_const_1 ] = QQ(_sage_const_20 )
p_zud[_sage_const_2 ] = QQ(_sage_const_7425 ) / QQ(_sage_const_16 )

for n_val in range(N-_sage_const_3 ):
    val = sum(P_rec[j](nn=n_val) * p_zud[n_val + j] for j in range(_sage_const_3 ))
    p_zud[n_val + _sage_const_3 ] = -val / P_rec[_sage_const_3 ](nn=n_val)

# ============================================================
# CORRECT P2.7 recurrence
# ============================================================
def A_p27(n):
    return QQ(_sage_const_1024 ) * (_sage_const_2 *n+_sage_const_5 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 )

def B_p27(n):
    return QQ(_sage_const_128 ) * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_104060 *n**_sage_const_6  + _sage_const_1745370 *n**_sage_const_5  +
        _sage_const_12145238 *n**_sage_const_4  + _sage_const_44886481 *n**_sage_const_3  + _sage_const_92943995 *n**_sage_const_2  + _sage_const_102256019 *n + _sage_const_46709052 )

def C_p27(n):
    return QQ(_sage_const_16 ) * (n+_sage_const_3 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_3784 *n**_sage_const_5  + _sage_const_57792 *n**_sage_const_4  +
        _sage_const_351019 *n**_sage_const_3  + _sage_const_1059230 *n**_sage_const_2  + _sage_const_1587211 *n + _sage_const_944620 )

def D_p27(n):
    return QQ(_sage_const_1 ) * (n+_sage_const_3 )**_sage_const_4  * (n+_sage_const_4 )**_sage_const_6  * (_sage_const_946 *n**_sage_const_2  + _sage_const_4515 *n + _sage_const_5399 )

q_p27 = [QQ(_sage_const_0 )] * N
q_p27[_sage_const_0 ] = QQ(-_sage_const_215040420000 )
q_p27[_sage_const_1 ] = QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 )
q_p27[_sage_const_2 ] = QQ(-_sage_const_964185327658080 ) / QQ(_sage_const_6071 )

p_p27 = [QQ(_sage_const_0 )] * N
p_p27[_sage_const_0 ] = QQ(-_sage_const_612218384750 )
p_p27[_sage_const_1 ] = QQ(-_sage_const_9525021973931919 ) / QQ(_sage_const_18100 )
p_p27[_sage_const_2 ] = QQ(-_sage_const_29561828382772029 ) / QQ(_sage_const_65380 )

for n in range(_sage_const_2 , N-_sage_const_1 ):
    q_p27[n+_sage_const_1 ] = B_p27(n)/A_p27(n) * q_p27[n] - C_p27(n-_sage_const_1 )/A_p27(n-_sage_const_1 ) * q_p27[n-_sage_const_1 ] + D_p27(n-_sage_const_2 )/A_p27(n-_sage_const_2 ) * q_p27[n-_sage_const_2 ]
    p_p27[n+_sage_const_1 ] = B_p27(n)/A_p27(n) * p_p27[n] - C_p27(n-_sage_const_1 )/A_p27(n-_sage_const_1 ) * p_p27[n-_sage_const_1 ] + D_p27(n-_sage_const_2 )/A_p27(n-_sage_const_2 ) * p_p27[n-_sage_const_2 ]

# ============================================================
# Compute errors
# ============================================================
L = mpmath.zeta(_sage_const_2 ) + mpmath.zeta(_sage_const_3 )

e_zud = []
e_p27 = []
for n_val in range(min(_sage_const_40 , N)):
    ez = mpmath.mpf(p_zud[n_val]) - L * mpmath.mpf(a_list[n_val])
    e_zud.append(ez)

    ep = mpmath.mpf(p_p27[n_val].numerator()) / mpmath.mpf(p_p27[n_val].denominator()) - L * mpmath.mpf(q_p27[n_val].numerator()) / mpmath.mpf(q_p27[n_val].denominator())
    e_p27.append(ep)

# ============================================================
# Error decay rates
# ============================================================
print("=== Zudilin error decay |e^Z_{n+1}/e^Z_n| ===")
for n_val in range(min(_sage_const_25 , len(e_zud)-_sage_const_1 )):
    if abs(e_zud[n_val]) > _sage_const_0 :
        r = e_zud[n_val+_sage_const_1 ] / e_zud[n_val]
        print("n=%2d: ratio = %s, |ratio| = %s" % (n_val, mpmath.nstr(r, _sage_const_12 ), mpmath.nstr(abs(r), _sage_const_12 )))

print("\n=== P2.7 error decay |e^P_{n+1}/e^P_n| ===")
for n_val in range(min(_sage_const_25 , len(e_p27)-_sage_const_1 )):
    if abs(e_p27[n_val]) > _sage_const_0 :
        r = e_p27[n_val+_sage_const_1 ] / e_p27[n_val]
        print("n=%2d: ratio = %s, |ratio| = %s" % (n_val, mpmath.nstr(r, _sage_const_12 ), mpmath.nstr(abs(r), _sage_const_12 )))

# ============================================================
# Error ratios
# ============================================================
print("\n=== Raw ratio e^P_n / e^Z_n ===")
for n_val in range(min(_sage_const_25 , len(e_zud))):
    if abs(e_zud[n_val]) > _sage_const_0  and abs(e_p27[n_val]) > _sage_const_0 :
        r = e_p27[n_val] / e_zud[n_val]
        print("n=%2d: %s" % (n_val, mpmath.nstr(r, _sage_const_15 )))

print("\n=== 64-scaled ratio e^P_n / (64^{-n} · e^Z_n) ===")
for n_val in range(min(_sage_const_25 , len(e_zud))):
    if abs(e_zud[n_val]) > _sage_const_0  and abs(e_p27[n_val]) > _sage_const_0 :
        r = e_p27[n_val] / (mpmath.power(_sage_const_64 , -n_val) * e_zud[n_val])
        print("n=%2d: %s" % (n_val, mpmath.nstr(r, _sage_const_15 )))

# ============================================================
# |e^P_n| · 64^n / |e^Z_n| — should behave like n^{-10.5}
# ============================================================
print("\n=== |e^P_n| · 64^n / |e^Z_n| ===")
ratios_scaled = []
for n_val in range(min(_sage_const_30 , len(e_zud))):
    if abs(e_zud[n_val]) > _sage_const_0  and abs(e_p27[n_val]) > _sage_const_0 :
        r = abs(e_p27[n_val]) * mpmath.power(_sage_const_64 , n_val) / abs(e_zud[n_val])
        ratios_scaled.append((n_val, float(r)))
        print("n=%2d: %s" % (n_val, mpmath.nstr(r, _sage_const_12 )))

# Check power law: log ratio / log n
print("\nlog |ratio| / log n (should → ~-10.5 if ratio ~ n^{-10.5}):")
import math
for n_val, r in ratios_scaled:
    if n_val >= _sage_const_2  and r > _sage_const_0 :
        print("n=%2d: log(r)/log(n) = %.4f" % (n_val, math.log(r)/math.log(n_val)))

# ============================================================
# Check successive log ratio — fits n^α with what α?
# ============================================================
print("\n=== Successive ratio (should → constant if power law) ===")
print("r_{n+1}/r_n · n/(n+1) for power law detection:")
for i in range(_sage_const_1 , len(ratios_scaled)):
    n1, r1 = ratios_scaled[i-_sage_const_1 ]
    n2, r2 = ratios_scaled[i]
    if r1 > _sage_const_0  and n1 > _sage_const_0 :
        actual_ratio = r2/r1
        print("n=%d→%d: r_{n+1}/r_n = %.6f" % (n1, n2, actual_ratio))

# ============================================================
# Also check the gauge q^P / (64^{-n} a_n) with correct recurrence
# ============================================================
print("\n=== Gauge: q^P_n · 64^n / a_n (CORRECT recurrence) ===")
for n_val in range(min(_sage_const_20 , N)):
    if a_list[n_val] != _sage_const_0 :
        g = mpmath.mpf(q_p27[n_val]) * mpmath.power(_sage_const_64 , n_val) / mpmath.mpf(a_list[n_val])
        print("n=%2d: %s" % (n_val, mpmath.nstr(g, _sage_const_15 )))

# ============================================================
# Try to identify the P2.7 recurrence in standard form
# ============================================================
# Multiply through to clear denominators:
# A_n A_{n-1} A_{n-2} u_{n+1} = B_n A_{n-1} A_{n-2} u_n
#   - C_{n-1} A_n A_{n-2} u_{n-1} + D_{n-2} A_n A_{n-1} u_{n-2}
#
